# CinePop - Sistema de Reservas de Ingressos de Cinema
# Trabalho de Programação Orientada a Objetos (POO)
#
# O sistema é dividido em 3 serviços (microsserviços), cada um em uma classe:
#   1. Cartaz     -> filmes e horários
#   2. Poltronas  -> mapa de poltronas e ingressos vendidos
#   3. Pagamento  -> pagamento simulado e código do ingresso
# E mais a classe Usuarios, que cuida do login (cadastro e entrada no app).
# Todos guardam os dados no banco SQLite cinepop.db.
#
# A interface tem uma tela para cada etapa da compra:
#   Login -> Filme -> Sessão (horário e poltronas) -> Pagamento -> Ingresso
# Cada tela é uma classe que HERDA da classe Tela.

import hashlib
import math
import random
import sqlite3
import tkinter as tk
from datetime import datetime
from tkinter import font as tkfont
from tkinter import messagebox

# ---------- Cores do app: identidade visual de cinema retrô ----------
# (vermelho de cortina de cinema, creme de ingresso antigo, preto de fita de filme
#  e amarelo mostarda de pipoca)
FUNDO = "#9E1B1B"            # vermelho do fundo
FUNDO_RAIO = "#A92424"       # raios de sol do fundo, estilo pôster antigo
FUNDO_ESCURO = "#7A1414"
VERMELHO = "#B81D24"
VERMELHO_VIVO = "#E0262E"
VERMELHO_ESCURO = "#7A1414"
CREME = "#F7EEDF"
CREME_SUAVE = "#EBCFC2"
FUNDO_CAIXA = "#2E2523"
PRETO = "#1A1414"
CARTAO = "#161111"           # fundo preto dos cards
TEXTO_SUAVE = "#B5A49A"      # texto secundário nos cards pretos
LINHA = "#4A3C38"
MOSTARDA = "#EAB02F"
MOSTARDA_HOVER = "#D49A1E"
SOMBRA = "#5E0E0E"
SALA = "#1A1414"             # sala de cinema escura
FURO = "#4A3F3B"             # furinhos da fita de filme
POLTRONA_LIVRE = "#E9DCC6"
POLTRONA_OCUPADA = "#2E2523"

CLASSIFICACAO = {"L": ("#22A447", "white"), "10": ("#1D8FE1", "white"),
                 "12": ("#F2C300", "black"), "14": ("#F07D00", "white"), "16": ("#D7262C", "white"),
                 "18": ("#000000", "white")}

LARGURA = 1040
ALTURA = 700
FILEIRAS = ["A", "B", "C", "D", "E", "F"]
POLTRONAS_POR_FILEIRA = 10
MAXIMO_POLTRONAS = 6
FONTE = "Arial"          # fonte dos textos (trocada quando o app abre)
FONTE_TITULO = "Impact"  # fonte condensada dos títulos, estilo pôster de cinema
HOJE = "19/11"    # dia da apresentação
ANO = "2026"


def fonte(tamanho, peso="normal"):
    # tamanho negativo = tamanho em pixels (fica igual no Mac e no Windows)
    return (FONTE, -tamanho, peso)


def titulo_fonte(tamanho):
    return (FONTE_TITULO, -tamanho, "bold")


def data_da_sessao(filme):
    # filme em pré-venda passa no dia da estreia; os outros passam hoje
    return filme[8] if filme[8] else HOJE


# Imagens dos cartazes já abertas (o Tkinter precisa guardar a imagem numa variável)
imagens_abertas = {}


def imagem_do_cartaz(filme_id, largura, altura):
    # CARTAZES fica lá no fim do arquivo: imagens PNG guardadas como texto (base64)
    chave = f"{filme_id}_{largura}x{altura}"
    if chave not in CARTAZES:
        return None
    if chave not in imagens_abertas:
        imagens_abertas[chave] = tk.PhotoImage(data=CARTAZES[chave])
    return imagens_abertas[chave]


def reais(valor):
    # 25.0 -> "R$ 25,00"
    return f"R$ {valor:.2f}".replace(".", ",")


# =====================================================================
#                        SERVIÇOS (banco de dados)
# =====================================================================

# ---------- Serviço 1: Cartaz de Filmes e Horários ----------
class Cartaz:
    def __init__(self, banco):
        self.banco = banco
        # O cartaz é montado de novo toda vez que o app abre
        # (assim, se mudarmos os filmes no código, o banco já pega a versão nova)
        self.banco.execute("DROP TABLE IF EXISTS filmes")
        self.banco.execute("DROP TABLE IF EXISTS horarios")
        self.banco.execute("CREATE TABLE IF NOT EXISTS filmes "
                           "(id INTEGER PRIMARY KEY, titulo TEXT, genero TEXT, duracao TEXT, "
                           "classificacao TEXT, emoji TEXT, cor TEXT, sinopse TEXT, pre_venda TEXT)")
        self.banco.execute("CREATE TABLE IF NOT EXISTS horarios "
                           "(id INTEGER PRIMARY KEY, filme_id INTEGER, hora TEXT, sala TEXT, "
                           "formato TEXT, preco REAL)")
        self.cadastrar_filmes()

    def cadastrar_filmes(self):
        # pre_venda: None = em cartaz hoje; "16/12" = pré-venda, a sessão é no dia da estreia
        filmes = [
            (1, "Jogos Vorazes: Amanhecer na Colheita", "Ação", "2h 37min", "14", "🏹", "#C2410C",
             "Na 50ª edição dos Jogos Vorazes, o jovem Haymitch Abernathy é sorteado "
             "e precisa sobreviver à arena.", None),
            (2, "Verity", "Suspense", "2h 05min", "16", "📖", "#7A0F1E",
             "A escritora Lowen é chamada para terminar os livros de Verity Crawford "
             "e encontra na casa dela um manuscrito assustador.", None),
            (3, "Vingadores: Doutor Destino", "Ação", "2h 40min", "14", "🛡️", "#3B5BDB",
             "Os Vingadores se reúnem para enfrentar o Doutor Destino, a maior ameaça "
             "que o multiverso já viu.", "16/12"),
            (4, "Duna: Parte 3", "Ficção científica", "2h 45min", "14", "🪐", "#B08968",
             "Anos depois de virar imperador, Paul Atreides enfrenta as consequências "
             "da guerra santa que começou.", "15/12"),
        ]
        horarios = [
            (1, 1, "14:00", "Sala 1", "Dublado", 26.0),
            (2, 1, "17:30", "Sala 1", "Legendado", 28.0),
            (3, 1, "21:00", "Sala 3", "IMAX", 42.0),
            (4, 2, "16:00", "Sala 2", "Dublado", 24.0),
            (5, 2, "19:30", "Sala 2", "Legendado", 26.0),
            (6, 2, "22:15", "Sala 4", "Legendado", 26.0),
            (7, 3, "18:00", "Sala 3", "3D", 36.0),
            (8, 3, "21:30", "Sala 3", "IMAX", 44.0),
            (9, 4, "17:00", "Sala 4", "Legendado", 32.0),
            (10, 4, "20:30", "Sala 5", "IMAX", 44.0),
        ]
        self.banco.executemany("INSERT INTO filmes VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)", filmes)
        self.banco.executemany("INSERT INTO horarios VALUES (?, ?, ?, ?, ?, ?)", horarios)
        self.banco.commit()

    def listar_filmes(self):
        return self.banco.execute("SELECT * FROM filmes ORDER BY id").fetchall()

    def listar_horarios(self, filme_id):
        return self.banco.execute("SELECT * FROM horarios WHERE filme_id = ? ORDER BY hora",
                                  (filme_id,)).fetchall()


# ---------- Serviço 2: Mapa de Poltronas ----------
class Poltronas:
    def __init__(self, banco):
        self.banco = banco
        # UNIQUE: a mesma poltrona não pode ser vendida duas vezes no mesmo horário
        self.banco.execute("CREATE TABLE IF NOT EXISTS ingressos "
                           "(horario_id INTEGER, poltrona TEXT, cliente TEXT, codigo TEXT, "
                           "UNIQUE(horario_id, poltrona))")
        quantidade = self.banco.execute("SELECT COUNT(*) FROM ingressos").fetchone()[0]
        if quantidade == 0:
            self.simular_vendas_anteriores()

    def simular_vendas_anteriores(self):
        # Deixa algumas poltronas ocupadas para o mapa parecer de verdade
        sorteio = random.Random(7)
        todas = [f"{fileira}{numero}" for fileira in FILEIRAS
                 for numero in range(1, POLTRONAS_POR_FILEIRA + 1)]
        for horario_id in range(1, 11):
            for poltrona in sorteio.sample(todas, sorteio.randint(8, 22)):
                self.banco.execute("INSERT INTO ingressos VALUES (?, ?, ?, ?)",
                                   (horario_id, poltrona, "Venda anterior", "-"))
        self.banco.commit()

    def ocupadas(self, horario_id):
        linhas = self.banco.execute("SELECT poltrona FROM ingressos WHERE horario_id = ?",
                                    (horario_id,)).fetchall()
        return [poltrona for (poltrona,) in linhas]

    def reservar(self, horario_id, lista_poltronas, cliente, codigo):
        try:
            with self.banco:   # ou salva todas as poltronas, ou nenhuma
                for poltrona in lista_poltronas:
                    self.banco.execute("INSERT INTO ingressos VALUES (?, ?, ?, ?)",
                                       (horario_id, poltrona, cliente, codigo))
            return True
        except sqlite3.IntegrityError:
            return False   # alguém já comprou uma dessas poltronas


# ---------- Serviço 3: Pagamento Simulado ----------
class Pagamento:
    def __init__(self, banco):
        self.banco = banco
        self.banco.execute("CREATE TABLE IF NOT EXISTS compras "
                           "(codigo TEXT PRIMARY KEY, cliente TEXT, valor REAL, "
                           "forma TEXT, data TEXT)")

    def gerar_codigo(self):
        letras = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
        return "CP-" + "".join(random.choices(letras, k=6))

    def pagar(self, codigo, cliente, valor, forma):
        data = f"{HOJE}/{ANO} " + datetime.now().strftime("%H:%M")
        self.banco.execute("INSERT INTO compras VALUES (?, ?, ?, ?, ?)",
                           (codigo, cliente, valor, forma, data))
        self.banco.commit()
        return True


# ---------- Login: cadastro e entrada dos usuários ----------
class Usuarios:
    def __init__(self, banco):
        self.banco = banco
        # PRIMARY KEY: não podem existir dois usuários com o mesmo nome de usuário
        self.banco.execute("CREATE TABLE IF NOT EXISTS usuarios "
                           "(usuario TEXT PRIMARY KEY, nome TEXT, senha TEXT)")
        self.banco.commit()

    def criptografar(self, senha):
        # a senha nunca é guardada como foi digitada, só o hash dela (SHA-256)
        return hashlib.sha256(senha.encode()).hexdigest()

    def cadastrar(self, nome, usuario, senha):
        try:
            with self.banco:
                self.banco.execute("INSERT INTO usuarios VALUES (?, ?, ?)",
                                   (usuario, nome, self.criptografar(senha)))
            return True
        except sqlite3.IntegrityError:
            return False   # esse usuário já existe

    def entrar(self, usuario, senha):
        linha = self.banco.execute("SELECT nome FROM usuarios WHERE usuario = ? AND senha = ?",
                                   (usuario, self.criptografar(senha))).fetchone()
        if linha is None:
            return None    # usuário ou senha errados
        return linha[0]    # devolve o nome da pessoa


# =====================================================================
#                        TELAS (interface gráfica)
# =====================================================================

# ---------- Classe mãe de todas as telas ----------
class Tela(tk.Canvas):
    etapa = 0   # cada tela filha diz qual etapa ela é

    def __init__(self, app):
        super().__init__(app.janela, width=LARGURA, height=ALTURA, bg=FUNDO,
                         highlightthickness=0)
        self.app = app
        self.contador = 0

    # Retângulo com cantos arredondados (o Tkinter não tem pronto)
    def retangulo(self, x1, y1, x2, y2, raio=12, **opcoes):
        r = raio
        pontos = [x1 + r, y1, x1 + r, y1, x2 - r, y1, x2 - r, y1, x2, y1, x2, y1 + r,
                  x2, y1 + r, x2, y2 - r, x2, y2 - r, x2, y2, x2 - r, y2, x2 - r, y2,
                  x1 + r, y2, x1 + r, y2, x1, y2, x1, y2 - r, x1, y2 - r, x1, y1 + r,
                  x1, y1 + r, x1, y1]
        return self.create_polygon(pontos, smooth=True, **opcoes)

    def nova_tag(self):
        self.contador += 1
        return f"item{self.contador}"

    # Faz um grupo de desenhos funcionar como botão
    def clicavel(self, tag, ao_clicar, ao_entrar=None, ao_sair=None):
        def entrar(evento):
            self.config(cursor="hand2")
            if ao_entrar:
                ao_entrar()

        def sair(evento):
            self.config(cursor="")
            if ao_sair:
                ao_sair()

        self.tag_bind(tag, "<Enter>", entrar)
        self.tag_bind(tag, "<Leave>", sair)
        self.tag_bind(tag, "<Button-1>", lambda evento: ao_clicar())

    def botao(self, x1, y1, x2, y2, texto, ao_clicar, tipo="primario", ativo=True):
        tag = self.nova_tag()
        if not ativo:
            cor, cor_hover, cor_texto, contorno = "#8E3A36", "#8E3A36", "#C98A84", "#8E3A36"
        elif tipo == "primario":
            cor, cor_hover, cor_texto, contorno = MOSTARDA, MOSTARDA_HOVER, PRETO, MOSTARDA
        else:
            cor, cor_hover, cor_texto, contorno = FUNDO, FUNDO_ESCURO, CREME, CREME
        forma = self.retangulo(x1, y1, x2, y2, 10, fill=cor, outline=contorno, width=2, tags=tag)
        self.create_text((x1 + x2) / 2, (y1 + y2) / 2, text=texto, fill=cor_texto,
                         font=titulo_fonte(18), tags=tag)
        if ativo:
            self.clicavel(tag, ao_clicar,
                          lambda: self.itemconfig(forma, fill=cor_hover),
                          lambda: self.itemconfig(forma, fill=cor))

    def selo_classificacao(self, x, y, classificacao, tamanho=26):
        cor, cor_texto = CLASSIFICACAO[classificacao]
        self.retangulo(x, y, x + tamanho, y + tamanho, 6, fill=cor, outline=cor)
        self.create_text(x + tamanho / 2, y + tamanho / 2, text=classificacao,
                         fill=cor_texto, font=fonte(int(tamanho * 0.5), "bold"))

    def cartaz_filme(self, x1, y1, x2, y2, filme, tamanho_emoji):
        # Se tiver a imagem do cartaz guardada no fim do arquivo, usa ela
        imagem = imagem_do_cartaz(filme[0], x2 - x1, y2 - y1)
        if imagem:
            self.create_image(x1, y1, image=imagem, anchor="nw")
        else:
            self.retangulo(x1, y1, x2, y2, 12, fill=filme[6], outline=filme[6])
            self.create_text((x1 + x2) / 2, (y1 + y2) / 2, text=filme[5],
                             font=fonte(tamanho_emoji))
        # Faixa de pré-venda embaixo do cartaz (só nos cartazes grandes)
        if filme[8] and tamanho_emoji >= 60:
            self.retangulo(x1 + 12, y2 - 44, x2 - 12, y2 - 12, 8, fill=MOSTARDA, outline=PRETO,
                           width=2)
            self.create_text((x1 + x2) / 2, y2 - 28, text=f"PRÉ-VENDA  {filme[8]}",
                             fill=PRETO, font=titulo_fonte(19))

    # Fundo de pôster antigo: raios de sol saindo do centro + pontinhos de papel velho
    def fundo_retro(self, centro_y=420):
        self.create_rectangle(0, 0, LARGURA, ALTURA, fill=FUNDO, outline=FUNDO)
        centro_x = LARGURA / 2
        raios = 28
        for numero in range(0, raios, 2):
            angulo1 = 2 * math.pi * numero / raios
            angulo2 = 2 * math.pi * (numero + 1) / raios
            self.create_polygon(centro_x, centro_y,
                                centro_x + 1400 * math.cos(angulo1), centro_y + 1400 * math.sin(angulo1),
                                centro_x + 1400 * math.cos(angulo2), centro_y + 1400 * math.sin(angulo2),
                                fill=FUNDO_RAIO, outline=FUNDO_RAIO)
        sorteio = random.Random(3)
        for _ in range(260):
            x, y = sorteio.randint(0, LARGURA), sorteio.randint(80, ALTURA)
            tamanho = sorteio.choice([1, 1, 2, 3])
            self.create_oval(x, y, x + tamanho, y + tamanho, fill=FUNDO_ESCURO, outline="")

    # Barra de cima: fita de filme preta com o logo e as etapas da compra
    def cabecalho(self):
        self.fita_de_filme(0, 84)
        self.create_text(40, 42, text="🍿", font=fonte(30))
        logo = self.create_text(68, 44, text="CINE", anchor="w", fill=CREME,
                                font=titulo_fonte(40))
        self.create_text(self.bbox(logo)[2] + 2, 44, text="POP", anchor="w", fill=MOSTARDA,
                         font=titulo_fonte(40))
        if self.etapa < 0:
            return   # a tela de login não mostra as etapas da compra

        etapas = ["Filme", "Sessão", "Pagamento", "Ingresso"]
        x = 420
        for numero, nome in enumerate(etapas):
            if numero < self.etapa:
                fundo, simbolo, cor_simbolo, cor_nome = CREME, "✓", PRETO, CREME
            elif numero == self.etapa:
                fundo, simbolo, cor_simbolo, cor_nome = MOSTARDA, str(numero + 1), PRETO, MOSTARDA
            else:
                fundo, simbolo, cor_simbolo, cor_nome = PRETO, str(numero + 1), "#8C7F78", "#8C7F78"
            self.create_oval(x, 30, x + 24, 54, fill=fundo,
                             outline=fundo if numero <= self.etapa else "#5A4E4A", width=2)
            self.create_text(x + 12, 42, text=simbolo, fill=cor_simbolo, font=fonte(12, "bold"))
            nome_item = self.create_text(x + 32, 42, text=nome.upper(), anchor="w", fill=cor_nome,
                                         font=titulo_fonte(19))
            fim_nome = self.bbox(nome_item)[2]
            if numero < len(etapas) - 1:
                cor_linha = CREME if numero < self.etapa else "#5A4E4A"
                self.create_line(fim_nome + 10, 42, fim_nome + 34, 42, fill=cor_linha, width=2)
            x = fim_nome + 44

    def fita_de_filme(self, y, altura=34):
        # Fita de filme preta com os furinhos em cima e embaixo
        self.create_rectangle(0, y, LARGURA, y + altura, fill=PRETO, outline=PRETO)
        for x in range(8, LARGURA, 28):
            self.retangulo(x, y + 4, x + 14, y + 11, 2, fill=FURO, outline=FURO)
            self.retangulo(x, y + altura - 11, x + 14, y + altura - 4, 2, fill=FURO, outline=FURO)

    def titulo(self, texto, subtitulo):
        self.create_text(40, 126, text=texto, anchor="w", fill=CREME, font=titulo_fonte(46))
        self.create_text(40, 162, text=subtitulo, anchor="w", fill=CREME_SUAVE, font=fonte(15))

    def inicio_da_tela(self):
        self.delete("all")
        self.config(cursor="")
        self.fundo_retro()
        self.cabecalho()

    def desenhar(self):
        pass   # cada tela filha desenha o seu conteúdo


# ---------- Tela 0: login (entrar ou criar conta) ----------
class TelaEntrada(Tela):
    etapa = -1
    rotulos = {"nome": "SEU NOME", "usuario": "USUÁRIO", "senha": "SENHA"}

    def __init__(self, app):
        super().__init__(app)
        self.modo = "entrar"      # ou "cadastrar"
        self.erro = ""
        self.campos = {}
        for nome in self.rotulos:
            campo = tk.Entry(self, font=fonte(16), bg=CARTAO, fg=CREME, relief="flat",
                             insertbackground=CREME, highlightthickness=0, bd=0,
                             show="•" if nome == "senha" else "")
            campo.bind("<Return>", lambda evento: self.confirmar())
            self.campos[nome] = campo

    def desenhar(self):
        self.inicio_da_tela()
        centro = LARGURA / 2
        cadastrar = self.modo == "cadastrar"
        nomes_campos = ["nome", "usuario", "senha"] if cadastrar else ["usuario", "senha"]

        x1, x2, y1 = 300, 740, 116
        altura = 250 + len(nomes_campos) * 84 + (26 if self.erro else 0)
        y2 = y1 + altura
        self.retangulo(x1 + 6, y1 + 8, x2 + 6, y2 + 8, 14, fill=SOMBRA, outline=SOMBRA)
        self.retangulo(x1, y1, x2, y2, 14, fill=CARTAO, outline=CARTAO)

        self.create_text(centro, y1 + 46, text="CRIAR CONTA" if cadastrar else "ENTRAR",
                         fill=CREME, font=titulo_fonte(42))
        self.create_text(centro, y1 + 84, fill=TEXTO_SUAVE, font=fonte(14),
                         text="Cadastre-se para comprar seus ingressos" if cadastrar
                         else "Faça login para comprar seus ingressos")

        y = y1 + 116
        for nome in nomes_campos:
            self.create_text(x1 + 34, y, text=self.rotulos[nome], anchor="w", fill=MOSTARDA,
                             font=titulo_fonte(18))
            self.retangulo(x1 + 34, y + 14, x2 - 34, y + 60, 10, fill=FUNDO_CAIXA,
                           outline=FUNDO_CAIXA)
            self.campos[nome].config(bg=FUNDO_CAIXA)
            self.create_window(x1 + 50, y + 37, window=self.campos[nome], anchor="w",
                               width=x2 - x1 - 100, height=30)
            y += 84

        if self.erro:
            self.create_text(centro, y + 2, text="⚠  " + self.erro, fill=MOSTARDA,
                             font=fonte(13, "bold"))
            y += 26

        self.botao(x1 + 34, y + 14, x2 - 34, y + 60, "CRIAR CONTA" if cadastrar else "ENTRAR",
                   self.confirmar)

        # link para trocar entre "entrar" e "criar conta"
        tag = self.nova_tag()
        link = self.create_text(centro, y + 92, tags=tag, fill=CREME, font=fonte(14, "bold"),
                                text="Já tem conta? Entrar" if cadastrar
                                else "Não tem conta? Criar conta")
        self.clicavel(tag, self.trocar_modo,
                      lambda: self.itemconfig(link, fill=MOSTARDA),
                      lambda: self.itemconfig(link, fill=CREME))

        self.fita_de_filme(ALTURA - 40, 40)
        self.campos[nomes_campos[0]].focus_set()

    def trocar_modo(self):
        self.modo = "entrar" if self.modo == "cadastrar" else "cadastrar"
        self.erro = ""
        self.desenhar()

    def confirmar(self):
        nome = self.campos["nome"].get().strip()
        usuario = self.campos["usuario"].get().strip().lower()
        senha = self.campos["senha"].get()

        if self.modo == "cadastrar":
            if nome == "" or usuario == "" or senha == "":
                self.erro = "Preencha todos os campos"
            elif len(senha) < 4:
                self.erro = "A senha precisa ter pelo menos 4 caracteres"
            elif not self.app.usuarios.cadastrar(nome, usuario, senha):
                self.erro = "Esse usuário já existe, escolha outro"
            else:
                self.app.entrar_no_app(nome)
                return
        else:
            if usuario == "" or senha == "":
                self.erro = "Digite o usuário e a senha"
            else:
                nome_encontrado = self.app.usuarios.entrar(usuario, senha)
                if nome_encontrado is None:
                    self.erro = "Usuário ou senha incorretos"
                else:
                    self.app.entrar_no_app(nome_encontrado)
                    return
        self.desenhar()


# ---------- Tela 1: escolher o filme ----------
class TelaFilmes(Tela):
    etapa = 0

    def desenhar(self):
        self.inicio_da_tela()
        self.titulo("EM CARTAZ", f"Olá, {self.app.usuario}!  ·  Hoje, {HOJE}  ·  "
                                 "Escolha um filme para ver as sessões")

        largura_cartao, espaco = 225, 20
        y1, y2 = 192, 634
        for posicao, filme in enumerate(self.app.cartaz.listar_filmes()):
            x1 = 40 + posicao * (largura_cartao + espaco)
            x2 = x1 + largura_cartao
            tag = self.nova_tag()
            self.retangulo(x1 + 5, y1 + 6, x2 + 5, y2 + 6, 14, fill=SOMBRA, outline=SOMBRA)
            fundo = self.retangulo(x1, y1, x2, y2, 14, fill=CARTAO, outline=CARTAO, width=3)
            self.cartaz_filme(x1 + 12, y1 + 12, x2 - 12, y1 + 272, filme, 80)
            self.selo_classificacao(x1 + 22, y1 + 22, filme[4])
            nome = self.create_text(x1 + 16, y1 + 286, text=filme[1].upper(), anchor="nw",
                                    fill=CREME, font=titulo_fonte(23), width=largura_cartao - 30)
            self.create_text(x1 + 16, self.bbox(nome)[3] + 6, text=f"{filme[2]}  ·  {filme[3]}",
                             anchor="nw", fill=TEXTO_SUAVE, font=fonte(13))
            self.create_line(x1 + 16, y2 - 44, x2 - 16, y2 - 44, fill=LINHA, dash=(4, 4))
            self.create_text(x1 + 16, y2 - 22, text="🎟  VER SESSÕES", anchor="w",
                             fill=MOSTARDA, font=titulo_fonte(20))
            # todo o cartão vira um botão
            for item in self.find_overlapping(x1 + 1, y1 + 1, x2 - 1, y2 - 1):
                if item >= fundo:   # só o que foi desenhado em cima do cartão
                    self.addtag_withtag(tag, item)
            self.clicavel(tag, lambda f=filme: self.app.escolher_filme(f),
                          lambda f=fundo: self.itemconfig(f, outline=MOSTARDA),
                          lambda f=fundo: self.itemconfig(f, outline=CARTAO))

        self.fita_de_filme(ALTURA - 40, 40)
        self.create_text(LARGURA / 2, ALTURA - 20, text="🍿  PRÉ-VENDA: GARANTA SEU LUGAR ANTES DA "
                         "ESTREIA  ·  INGRESSOS COM ASSENTO MARCADO  🍿", fill=CREME_SUAVE,
                         font=titulo_fonte(16))


# ---------- Tela 2: escolher horário e poltronas ----------
class TelaSessao(Tela):
    etapa = 1

    def desenhar(self):
        self.inicio_da_tela()
        filme = self.app.filme

        # --- Coluna da esquerda: filme + horários ---
        self.cartaz_filme(40, 104, 140, 244, filme, 46)
        nome = self.create_text(156, 102, text=filme[1].upper(), anchor="nw", fill=CREME,
                                font=titulo_fonte(24), width=190)
        y = self.bbox(nome)[3] + 6
        self.create_text(156, y, text=f"{filme[2]}  ·  {filme[3]}", anchor="nw", fill=CREME_SUAVE,
                         font=fonte(13))
        self.selo_classificacao(156, y + 26, filme[4], 24)
        self.create_text(40, max(256, y + 64), text=filme[7], anchor="nw", fill=CREME_SUAVE,
                         font=fonte(13), width=300)

        if filme[8]:
            titulo_horarios = f"PRÉ-VENDA  ·  SESSÕES DE {filme[8]}"
        else:
            titulo_horarios = f"SESSÕES DE HOJE, {HOJE}"
        self.create_text(40, 346, text=titulo_horarios, anchor="w", fill=MOSTARDA,
                         font=titulo_fonte(22))
        y = 366
        for horario in self.app.cartaz.listar_horarios(filme[0]):
            self.cartao_horario(40, y, 340, y + 62, horario)
            y += 74

        # --- Coluna da direita: a sala de cinema ---
        self.retangulo(375, 100, 1005, 592, 18, fill=SALA, outline=PRETO, width=3)
        if self.app.horario is None:
            self.create_text(690, 300, text="🎬", font=fonte(56))
            self.create_text(690, 372, text="ESCOLHA UMA SESSÃO", fill=CREME, font=titulo_fonte(32))
            self.create_text(690, 404, text="para ver as poltronas disponíveis", fill=CREME_SUAVE,
                             font=fonte(14))
        else:
            self.mapa_poltronas()

        # --- Barra de baixo ---
        self.create_rectangle(0, 606, LARGURA, ALTURA, fill=FUNDO_ESCURO, outline=FUNDO_ESCURO)
        escolhidas = self.app.poltronas_escolhidas
        if escolhidas:
            preco = self.app.horario[5]
            self.create_text(40, 632, text="POLTRONAS: " + ", ".join(sorted(escolhidas)),
                             anchor="w", fill=CREME_SUAVE, font=titulo_fonte(18))
            self.create_text(40, 664, text=f"TOTAL  {reais(preco * len(escolhidas))}",
                             anchor="w", fill=MOSTARDA, font=titulo_fonte(30))
        else:
            self.create_text(40, 652, text="NENHUMA POLTRONA ESCOLHIDA", anchor="w",
                             fill=CREME_SUAVE, font=titulo_fonte(20))
        self.botao(700, 627, 840, 677, "← VOLTAR", self.app.voltar_para_filmes, "secundario")
        self.botao(856, 627, 1000, 677, "CONTINUAR", self.app.ir_para_pagamento,
                   ativo=bool(escolhidas))

    def cartao_horario(self, x1, y1, x2, y2, horario):
        escolhido = self.app.horario is not None and self.app.horario[0] == horario[0]
        tag = self.nova_tag()
        fundo = self.retangulo(x1, y1, x2, y2, 10, tags=tag, width=3,
                               fill=MOSTARDA if escolhido else CARTAO,
                               outline=PRETO if escolhido else CARTAO)
        self.create_text(x1 + 18, y1 + 24, text=horario[2], anchor="w",
                         fill=PRETO if escolhido else CREME,
                         font=titulo_fonte(30), tags=tag)
        self.create_text(x1 + 18, y1 + 47, text=f"{horario[3]}  ·  {horario[4]}", anchor="w",
                         fill=TEXTO_SUAVE if not escolhido else PRETO, font=fonte(13), tags=tag)
        self.create_text(x2 - 18, (y1 + y2) / 2, text=reais(horario[5]), anchor="e",
                         fill=MOSTARDA if not escolhido else PRETO, font=titulo_fonte(24), tags=tag)
        if not escolhido:
            self.clicavel(tag, lambda: self.app.escolher_horario(horario),
                          lambda: self.itemconfig(fundo, outline=MOSTARDA),
                          lambda: self.itemconfig(fundo, outline=CARTAO))

    def mapa_poltronas(self):
        centro = 690
        # Tela do cinema com a luz do projetor
        self.create_polygon(470, 140, 910, 140, 980, 470, 400, 470, fill="#241B19", outline="")
        for largura, cor in [(16, "#3A2F22"), (9, "#7A6233"), (4, CREME)]:
            self.create_line(475, 146, centro, 128, 905, 146, smooth=True, width=largura,
                             fill=cor, capstyle="round")
        self.create_text(centro, 164, text="T E L A", fill=CREME_SUAVE, font=titulo_fonte(16))

        ocupadas = self.app.poltronas.ocupadas(self.app.horario[0])
        tamanho, passo, corredor = 32, 42, 26
        largura_total = POLTRONAS_POR_FILEIRA * passo - (passo - tamanho) + corredor
        x_inicio = centro - largura_total / 2
        for linha, fileira in enumerate(FILEIRAS):
            y = 196 + linha * 46
            for x_letra in (x_inicio - 22, x_inicio + largura_total + 22):
                self.create_text(x_letra, y + tamanho / 2, text=fileira, fill=MOSTARDA,
                                 font=titulo_fonte(20))
            for numero in range(1, POLTRONAS_POR_FILEIRA + 1):
                x = x_inicio + (numero - 1) * passo
                if numero > POLTRONAS_POR_FILEIRA / 2:
                    x += corredor
                self.poltrona(x, y, tamanho, f"{fileira}{numero}", ocupadas)

        # Legenda
        y = 500
        x = centro - 175
        for cor, contorno, nome in [(POLTRONA_LIVRE, POLTRONA_LIVRE, "LIVRE"),
                                     (VERMELHO_VIVO, VERMELHO_VIVO, "ESCOLHIDA"),
                                     (POLTRONA_OCUPADA, "#4A3C38", "OCUPADA")]:
            self.retangulo(x, y, x + 20, y + 18, 5, fill=cor, outline=contorno)
            item = self.create_text(x + 28, y + 10, text=nome, anchor="w", fill=CREME_SUAVE,
                                    font=titulo_fonte(18))
            x = self.bbox(item)[2] + 34
        self.create_text(centro, 552, text=f"Até {MAXIMO_POLTRONAS} poltronas por compra",
                         fill="#8C7F78", font=fonte(12))

    def poltrona(self, x, y, tamanho, nome, ocupadas):
        tag = self.nova_tag()
        if nome in ocupadas:
            self.retangulo(x, y, x + tamanho, y + tamanho - 4, 8, fill=POLTRONA_OCUPADA,
                           outline="#4A3C38")
            self.create_text(x + tamanho / 2, y + tamanho / 2 - 2, text="×", fill="#5E504B",
                             font=fonte(14, "bold"))
            return
        escolhida = nome in self.app.poltronas_escolhidas
        cor = VERMELHO_VIVO if escolhida else POLTRONA_LIVRE
        forma = self.retangulo(x, y, x + tamanho, y + tamanho - 4, 8, fill=cor, outline=cor,
                               width=2, tags=tag)
        self.create_text(x + tamanho / 2, y + tamanho / 2 - 2, text=nome[1:], tags=tag,
                         fill=CREME if escolhida else PRETO, font=fonte(11, "bold"))
        self.clicavel(tag, lambda: self.app.marcar_poltrona(nome),
                      lambda: self.itemconfig(forma, outline=MOSTARDA),
                      lambda: self.itemconfig(forma, outline=cor))


# ---------- Tela 3: pagamento ----------
class TelaPagamento(Tela):
    etapa = 2
    formas = [("Pix", "⚡", "Aprovação na hora"),
              ("Cartão de crédito", "💳", "À vista, sem juros"),
              ("Cartão de débito", "🏦", "Desconta direto da conta")]

    def __init__(self, app):
        super().__init__(app)
        self.campo_nome = tk.Entry(self, font=fonte(16), bg=CARTAO, fg=CREME, relief="flat",
                                   insertbackground=CREME, highlightthickness=0, bd=0)
        self.campo_nome.insert(0, app.cliente)
        self.campo_nome.bind("<Return>", lambda evento: self.pagar())
        self.campo_nome.bind("<KeyRelease>", self.apagar_erro)
        self.erro_nome = False

    def desenhar(self):
        self.app.cliente = self.campo_nome.get()
        self.inicio_da_tela()
        self.titulo("PAGAMENTO", "Confira o pedido e escolha como pagar")

        # --- Nome ---
        self.create_text(40, 204, text="SEU NOME", anchor="w", fill=MOSTARDA, font=titulo_fonte(20))
        cor_borda = MOSTARDA if self.erro_nome else CARTAO
        self.retangulo(40, 220, 600, 270, 10, fill=CARTAO, outline=cor_borda, width=3)
        self.create_window(58, 245, window=self.campo_nome, anchor="w", width=524, height=30)
        if self.erro_nome:
            self.create_text(40, 286, text="⚠  Digite o seu nome para continuar", anchor="w",
                             fill=MOSTARDA, font=fonte(13, "bold"))

        # --- Formas de pagamento ---
        self.create_text(40, 322, text="FORMA DE PAGAMENTO", anchor="w", fill=MOSTARDA,
                         font=titulo_fonte(20))
        y = 340
        for nome, icone, descricao in self.formas:
            self.opcao_pagamento(40, y, 600, y + 64, nome, icone, descricao)
            y += 76

        # --- Resumo do pedido ---
        self.resumo(640, 104, 1000, 592)

        # --- Barra de baixo ---
        self.create_rectangle(0, 606, LARGURA, ALTURA, fill=FUNDO_ESCURO, outline=FUNDO_ESCURO)
        self.create_text(40, 652, text="🔒  Pagamento simulado  ·  nenhum valor é cobrado",
                         anchor="w", fill=CREME_SUAVE, font=fonte(13))
        self.botao(680, 627, 820, 677, "← VOLTAR", self.app.voltar_para_sessao, "secundario")
        self.botao(836, 627, 1000, 677, f"PAGAR {reais(self.app.total())}", self.pagar)

    def opcao_pagamento(self, x1, y1, x2, y2, nome, icone, descricao):
        escolhida = self.app.forma == nome
        tag = self.nova_tag()
        fundo = self.retangulo(x1, y1, x2, y2, 10, width=3, tags=tag,
                               fill=MOSTARDA if escolhida else CARTAO,
                               outline=PRETO if escolhida else CARTAO)
        centro_y = (y1 + y2) / 2
        self.create_oval(x1 + 20, centro_y - 10, x1 + 40, centro_y + 10, width=2, tags=tag,
                         fill=CREME, outline=PRETO if escolhida else TEXTO_SUAVE)
        if escolhida:
            self.create_oval(x1 + 25, centro_y - 5, x1 + 35, centro_y + 5, fill=VERMELHO,
                             outline=VERMELHO, tags=tag)
        self.create_text(x1 + 70, centro_y, text=icone, font=fonte(22), tags=tag)
        self.create_text(x1 + 98, centro_y - 11, text=nome.upper(), anchor="w",
                         fill=PRETO if escolhida else CREME,
                         font=titulo_fonte(23), tags=tag)
        self.create_text(x1 + 98, centro_y + 13, text=descricao, anchor="w",
                         fill=PRETO if escolhida else TEXTO_SUAVE, font=fonte(13), tags=tag)
        if not escolhida:
            self.clicavel(tag, lambda: self.escolher_forma(nome),
                          lambda: self.itemconfig(fundo, outline=MOSTARDA),
                          lambda: self.itemconfig(fundo, outline=CARTAO))

    def apagar_erro(self, evento=None):
        # some com o aviso assim que a pessoa começa a digitar
        if self.erro_nome and self.campo_nome.get().strip():
            self.erro_nome = False
            self.desenhar()
            self.campo_nome.focus_set()

    def escolher_forma(self, nome):
        self.app.forma = nome
        self.desenhar()

    def resumo(self, x1, y1, x2, y2):
        filme, horario = self.app.filme, self.app.horario
        self.retangulo(x1 + 5, y1 + 6, x2 + 5, y2 + 6, 14, fill=SOMBRA, outline=SOMBRA)
        self.retangulo(x1, y1, x2, y2, 14, fill=CARTAO, outline=CARTAO)
        self.create_rectangle(x1, y1 + 14, x2, y1 + 54, fill=VERMELHO, outline=VERMELHO)
        self.retangulo(x1, y1, x2, y1 + 30, 14, fill=VERMELHO, outline=VERMELHO)
        self.create_text((x1 + x2) / 2, y1 + 28, text="★  RESUMO DO PEDIDO  ★", fill=CREME,
                         font=titulo_fonte(24))
        self.cartaz_filme(x1 + 24, y1 + 72, x1 + 88, y1 + 162, filme, 30)
        nome = self.create_text(x1 + 104, y1 + 72, text=filme[1].upper(), anchor="nw", fill=CREME,
                                font=titulo_fonte(22), width=x2 - x1 - 124)
        self.create_text(x1 + 104, self.bbox(nome)[3] + 6, text=f"{horario[3]}  ·  {horario[4]}", anchor="nw",
                         fill=TEXTO_SUAVE, font=fonte(13))
        self.create_line(x1 + 24, y1 + 182, x2 - 24, y1 + 182, fill=LINHA, dash=(4, 4))

        quantidade = len(self.app.poltronas_escolhidas)
        linhas = [("Data", f"{data_da_sessao(filme)}/{ANO}"),
                  ("Horário", horario[2]),
                  ("Poltronas", ", ".join(sorted(self.app.poltronas_escolhidas))),
                  ("Ingressos", f"{quantidade} × {reais(horario[5])}")]
        y = y1 + 208
        for nome, valor in linhas:
            self.create_text(x1 + 24, y, text=nome, anchor="w", fill=TEXTO_SUAVE, font=fonte(14))
            self.create_text(x2 - 24, y, text=valor, anchor="e", fill=CREME, font=fonte(14, "bold"))
            y += 34
        self.create_line(x1 + 24, y + 4, x2 - 24, y + 4, fill=LINHA, dash=(4, 4))
        self.create_text(x1 + 24, y + 42, text="TOTAL", anchor="w", fill=CREME,
                         font=titulo_fonte(28))
        self.create_text(x2 - 24, y + 42, text=reais(self.app.total()), anchor="e",
                         fill=MOSTARDA, font=titulo_fonte(36))

    def pagar(self):
        nome = self.campo_nome.get().strip()
        if nome == "":
            self.erro_nome = True
            self.desenhar()
            self.campo_nome.focus_set()
            return
        self.app.cliente = nome
        self.app.finalizar_compra()


# ---------- Tela 4: ingresso pronto ----------
class TelaIngresso(Tela):
    etapa = 4   # todas as etapas ficam marcadas como feitas

    def desenhar(self):
        self.inicio_da_tela()
        filme, horario = self.app.filme, self.app.horario
        centro = LARGURA / 2
        self.create_text(centro, 122, text="✓  COMPRA CONFIRMADA!", fill=CREME,
                         font=titulo_fonte(44))
        self.create_text(centro, 156, text="Apresente o código na entrada da sala. Bom filme! 🍿",
                         fill=CREME_SUAVE, font=fonte(15))

        # Ingresso de papel: canhoto vermelho na esquerda + parte creme
        x1, y1, x2, y2 = 150, 182, 890, 546
        corte = 300
        self.retangulo(x1 + 6, y1 + 8, x2 + 6, y2 + 8, 14, fill=SOMBRA, outline=SOMBRA)
        self.retangulo(x1, y1, x2, y2, 14, fill=CARTAO, outline=CARTAO)
        self.retangulo(x1, y1, corte + 14, y2, 14, fill=VERMELHO, outline=VERMELHO)
        self.create_rectangle(corte - 10, y1, corte, y2, fill=VERMELHO, outline=VERMELHO)
        # código de barras no canhoto
        sorteio = random.Random(self.app.codigo)
        x = x1 + 26
        while x < x1 + 70:
            largura = sorteio.choice([2, 2, 3, 5])
            self.create_rectangle(x, y1 + 40, x + largura, y2 - 40, fill=CREME, outline=CREME)
            x += largura + sorteio.choice([2, 3])
        self.create_text(x1 + 112, (y1 + y2) / 2, text="ADMIT ONE  ★  CINEPOP", angle=90,
                         fill=CREME, font=titulo_fonte(30))
        # picote entre o canhoto e o ingresso
        self.create_oval(corte - 14, y1 - 14, corte + 14, y1 + 14, fill=FUNDO, outline=FUNDO)
        self.create_oval(corte - 14, y2 - 14, corte + 14, y2 + 14, fill=FUNDO, outline=FUNDO)
        self.create_line(corte, y1 + 22, corte, y2 - 22, fill=VERMELHO_ESCURO, dash=(6, 5), width=2)

        # parte principal do ingresso
        esquerda = corte + 34
        self.create_text(esquerda, y1 + 34, text="CINEPOP  ·  INGRESSO", anchor="w",
                         fill=VERMELHO_VIVO, font=titulo_fonte(20))
        self.selo_classificacao(x2 - 54, y1 + 22, filme[4], 26)
        nome = self.create_text(esquerda, y1 + 56, text=filme[1].upper(), anchor="nw", fill=CREME,
                                font=titulo_fonte(34), width=x2 - esquerda - 70)
        topo = self.bbox(nome)[3] + 10
        self.create_text(esquerda, topo, text="★ ★ ★", anchor="nw", fill=MOSTARDA,
                         font=fonte(14, "bold"))

        caixas = [("DATA", f"{data_da_sessao(filme)}/{ANO}"), ("HORÁRIO", horario[2]),
                  ("SALA", horario[3].replace("Sala ", "")),
                  ("POLTRONAS", ", ".join(sorted(self.app.poltronas_escolhidas)))]
        larguras = [118, 92, 70, 214]
        x = esquerda
        y = topo + 34
        for (rotulo, valor), largura in zip(caixas, larguras):
            self.create_text(x, y, text=rotulo, anchor="w", fill=TEXTO_SUAVE, font=fonte(11, "bold"))
            self.retangulo(x, y + 12, x + largura, y + 46, 6, fill=FUNDO_CAIXA, outline=FUNDO_CAIXA)
            tamanho = 22 if len(valor) <= 12 else 15   # várias poltronas: letra menor
            self.create_text(x + largura / 2, y + 29, text=valor, fill=CREME,
                             font=titulo_fonte(tamanho), width=largura - 8)
            x += largura + 12

        y = y + 66
        for coluna, (rotulo, valor) in enumerate([("CLIENTE", self.app.cliente),
                                                    ("PAGAMENTO", self.app.forma),
                                                    ("FORMATO", horario[4])]):
            x = esquerda + coluna * 180
            self.create_text(x, y, text=rotulo, anchor="w", fill=TEXTO_SUAVE, font=fonte(11, "bold"))
            self.create_text(x, y + 20, text=valor, anchor="w", fill=CREME, font=fonte(15, "bold"),
                             width=170)

        self.create_line(esquerda, y2 - 70, x2 - 30, y2 - 70, fill=LINHA, dash=(4, 4))
        self.create_text(esquerda, y2 - 52, text="CÓDIGO", anchor="w", fill=TEXTO_SUAVE,
                         font=fonte(11, "bold"))
        self.create_text(esquerda, y2 - 28, text=self.app.codigo, anchor="w", fill=CREME,
                         font=titulo_fonte(32))
        self.create_text(x2 - 30, y2 - 52, text="TOTAL PAGO", anchor="e", fill=TEXTO_SUAVE,
                         font=fonte(11, "bold"))
        self.create_text(x2 - 30, y2 - 28, text=reais(self.app.total()), anchor="e", fill=MOSTARDA,
                         font=titulo_fonte(32))

        self.botao(300, 572, 560, 618, "COMPRAR OUTRO INGRESSO", self.app.nova_compra)
        self.botao(576, 572, 740, 618, "SAIR", self.app.sair_da_conta, "secundario")
        self.fita_de_filme(ALTURA - 40, 40)


# =====================================================================
#                    APP: liga os serviços e as telas
# =====================================================================
class AppCinePop:
    def __init__(self):
        self.banco = sqlite3.connect("cinepop.db")
        self.cartaz = Cartaz(self.banco)
        self.poltronas = Poltronas(self.banco)
        self.pagamento = Pagamento(self.banco)
        self.usuarios = Usuarios(self.banco)
        self.usuario = None     # nome de quem fez login

        self.janela = tk.Tk()
        self.janela.title("CinePop")
        self.janela.configure(bg=FUNDO)
        self.janela.resizable(False, False)
        x = (self.janela.winfo_screenwidth() - LARGURA) // 2
        y = max(0, (self.janela.winfo_screenheight() - ALTURA) // 2 - 30)
        self.janela.geometry(f"{LARGURA}x{ALTURA}+{x}+{y}")
        self.escolher_fonte()

        self.tela = None
        self.mostrar(TelaEntrada)   # o app começa pelo login

    def escolher_fonte(self):
        # usa a primeira fonte da lista que estiver instalada no computador
        global FONTE, FONTE_TITULO
        instaladas = tkfont.families()
        for nome in ["Avenir Next", "Poppins", "Segoe UI", "Helvetica Neue", "Inter", "Arial"]:
            if nome in instaladas:
                FONTE = nome
                break
        for nome in ["Bebas Neue", "League Gothic", "DIN Condensed", "Impact",
                     "Bahnschrift Condensed", "Arial Narrow"]:
            if nome in instaladas:
                FONTE_TITULO = nome
                break

    def mostrar(self, classe_tela):
        if self.tela is not None:
            self.tela.destroy()
        self.tela = classe_tela(self)
        self.tela.pack()
        self.tela.desenhar()

    # ----- dados da compra -----
    def total(self):
        return self.horario[5] * len(self.poltronas_escolhidas)

    # ----- navegação entre as telas -----
    def nova_compra(self):
        self.filme = None
        self.horario = None
        self.poltronas_escolhidas = []
        self.cliente = self.usuario   # o nome já vem preenchido com o do login
        self.forma = "Pix"
        self.codigo = ""
        self.mostrar(TelaFilmes)

    def entrar_no_app(self, nome):
        self.usuario = nome
        self.nova_compra()

    def sair_da_conta(self):
        self.usuario = None
        self.mostrar(TelaEntrada)

    def escolher_filme(self, filme):
        self.filme = filme
        self.horario = None
        self.poltronas_escolhidas = []
        self.mostrar(TelaSessao)

    def voltar_para_filmes(self):
        self.mostrar(TelaFilmes)

    def escolher_horario(self, horario):
        self.horario = horario
        self.poltronas_escolhidas = []
        self.tela.desenhar()

    def marcar_poltrona(self, poltrona):
        if poltrona in self.poltronas_escolhidas:
            self.poltronas_escolhidas.remove(poltrona)
        elif len(self.poltronas_escolhidas) >= MAXIMO_POLTRONAS:
            messagebox.showinfo("Limite", f"Você pode escolher até {MAXIMO_POLTRONAS} poltronas.")
            return
        else:
            self.poltronas_escolhidas.append(poltrona)
        self.tela.desenhar()

    def ir_para_pagamento(self):
        self.mostrar(TelaPagamento)

    def voltar_para_sessao(self):
        self.cliente = self.tela.campo_nome.get()
        self.mostrar(TelaSessao)

    def finalizar_compra(self):
        codigo = self.pagamento.gerar_codigo()
        if not self.poltronas.reservar(self.horario[0], self.poltronas_escolhidas,
                                       self.cliente, codigo):
            messagebox.showerror("Poltrona ocupada",
                                 "Uma das poltronas acabou de ser vendida. Escolha outra.")
            self.poltronas_escolhidas = []
            self.mostrar(TelaSessao)
            return
        self.pagamento.pagar(codigo, self.cliente, self.total(), self.forma)
        self.codigo = codigo
        self.mostrar(TelaIngresso)

    def rodar(self):
        self.janela.mainloop()
        self.banco.close()


